notion_query_url = f"https://api.notion.com/v1/databases/{NOTION_DB_ID}/query"
query_response = requests.post(notion_query_url, headers=notion_headers)
if query_response.status_code != 200:
    print("❌ Notion DB 조회 실패:", query_response.text)
    exit(1)

db_data = query_response.json()
pages = db_data.get("results", [])
print(f"✅ 총 {len(pages)}개의 페이지 발견.")

# --- 각 페이지에 대해 작업 ---
for page in pages:
    page_id = page["id"]

    # Transcript 컬럼에서 텍스트 가져오기 ✅
    transcript_prop = page["properties"].get("Transcript")
    if not transcript_prop:
        print(f"⚠️ [{page_id}] Transcript 컬럼이 없습니다.")
        continue

    transcript_list = transcript_prop.get("rich_text", [])
    transcript = "".join([item.get("plain_text", "") for item in transcript_list]).strip()

    if not transcript:
        print(f"⚠️ [{page_id}] Transcript 내용이 비어 있습니다.")
        continue

    # --- 언어 감지 (영어/한국어 자동 감지) ---
    try:
        lang = detect(transcript)
    except Exception as e:
        print(f"❌ [{page_id}] 언어 감지 실패: {e}")
        continue

    # --- Gemini API에 보낼 프롬프트 작성 ---
    if lang == "ko":
        prompt = "아래 텍스트를 8~10줄로 요약해줘. 블로그, 유튜브 쇼츠, 인스타 릴스에 적합하도록 핵심 요약과 주요 포인트를 포함해줘."
    elif lang == "en":
        prompt = "Summarize the following text in 8-10 lines. Focus on the core summary and key takeaways, making it suitable for a blog, YouTube shorts, and Instagram reels."
    else:
        prompt = "Summarize the following text in 8-10 lines. Focus on the core summary and key takeaways, making it suitable for a blog, YouTube shorts, and Instagram reels."

    # --- Gemini API 요청 (JSON 형식 수정) ---
    gemini_payload = {
        "contents": [
            {"parts": [{"text": f"{prompt}\n\n{transcript}"}]}
        ]
    }
    gemini_params = {"key": GEMINI_API_KEY}

    gemini_resp = requests.post(gemini_url, params=gemini_params, json=gemini_payload)
    if gemini_resp.status_code != 200:
        print(f"❌ [{page_id}] Gemini API 호출 실패:", gemini_resp.text)
        continue

    gemini_data = gemini_resp.json()

    # ✅ Gemini API 응답에서 요약 추출 (수정된 구조 반영)
    try:
        summary = gemini_data["candidates"][0]["content"]["parts"][0]["text"]
    except KeyError:
        print(f"❌ [{page_id}] Gemini API 응답에서 요약 추출 실패:", gemini_data)
        continue

    # --- Notion 페이지 업데이트 (Abstract 컬럼이 없으면 추가) ---
    update_url = f"https://api.notion.com/v1/pages/{page_id}"

    # ✅ "Abstract" 컬럼이 존재하는지 확인
    if "Abstract" not in page["properties"]:
        print(f"⚠️ [{page_id}] Abstract 컬럼이 존재하지 않음. 새로 생성합니다.")
        update_payload = {
            "properties": {
                "Abstract": {
                    "title": [{"text": {"content": "요약"}}]
                }
            }
        }
        requests.patch(update_url, headers=notion_headers, json=update_payload)

    # ✅ Notion 업데이트 요청
    update_payload = {
        "properties": {
            "Abstract": {
                "rich_text": [
                    {"text": {"content": summary}}
                ]
            }
        }
    }
    update_resp = requests.patch(update_url, headers=notion_headers, json=update_payload)
    if update_resp.status_code != 200:
        print(f"❌ [{page_id}] Notion 업데이트 실패:", update_resp.text)
    else:
        print(f"✅ [{page_id}] 업데이트 성공")

    # ✅ API 호출 제한 고려해 딜레이 추가
    time.sleep(1)

